概述1、定义：将一个复杂对象的构建与它的表示分离，使得同样的构建过程可以创建不同的表示2、主要作用：在用户不知道对象的建造过程和细节的情况下就可以直接创建复杂的对象。3、如何使用：用户只需要给出指定复杂对象的类型和内容，建造者模式负责按顺序创建复杂对象（把内部的建造过程和细节隐藏起来）4、解决的问题：（1）、方便用户创建复杂的对象（不需要知道实现过程）（2）、代码复用性 &amp; 封装性（将对象构建过程和细节进行封装 &amp; 复用）5、注意事项：与工厂模式的区别是：建造者模式更加关注与零件装配的顺序，一般用来创建更为复杂的对象 实现方式代码实现 抽象建造者（builder）：描述具体建造者的公共接口，一般用来定义建造细节的方法，并不涉及具体的对象部件的创建。 具体建造者（ConcreteBuilder）：描述具体建造者，并实现抽象建造者公共接口。 指挥者（Director）：调用具体建造者来创建复杂对象（产品）的各个部分，并按照一定顺序（流程）来建造复杂对象。 产品（Product）：描述一个由一系列部件组成较为复杂的对象。 12345678910111213141516/** * Builder.java * 建造者 */abstract class Builder &#123; //地基 abstract void bulidA(); //钢筋工程 abstract void bulidB(); //铺电线 abstract void bulidC(); //粉刷 abstract void bulidD(); //完工-获取产品 abstract Product getProduct();&#125; 1234567891011121314151617181920212223242526272829303132333435363738/** * Product.java * 产品（房子） */public class Product &#123; private String buildA; private String buildB; private String buildC; private String buildD; public String getBuildA() &#123; return buildA; &#125; public void setBuildA(String buildA) &#123; this.buildA = buildA; &#125; public String getBuildB() &#123; return buildB; &#125; public void setBuildB(String buildB) &#123; this.buildB = buildB; &#125; public String getBuildC() &#123; return buildC; &#125; public void setBuildC(String buildC) &#123; this.buildC = buildC; &#125; public String getBuildD() &#123; return buildD; &#125; public void setBuildD(String buildD) &#123; this.buildD = buildD; &#125; @Override public String toString() &#123; return buildA+&quot;
&quot;+buildB+&quot;
&quot;+buildC+&quot;
&quot;+buildD+&quot;
&quot;+&quot;房子验收完成&quot;; &#125;&#125; 123456789101112131415161718192021222324252627282930/** * ConcreteBuilder.java * 具体建造者(工人) */public class ConcreteBuilder extends Builder&#123; private Product product; public ConcreteBuilder() &#123; product = new Product(); &#125; @Override void bulidA() &#123; product.setBuildA(&quot;地基&quot;); &#125; @Override void bulidB() &#123; product.setBuildB(&quot;钢筋工程&quot;); &#125; @Override void bulidC() &#123; product.setBuildC(&quot;铺电线&quot;); &#125; @Override void bulidD() &#123; product.setBuildD(&quot;粉刷&quot;); &#125; @Override Product getProduct() &#123; return product; &#125;&#125; 123456789101112131415/** * Director.java * 指挥者 */public class Director &#123; //指挥工人按顺序造房 public Product create(Builder builder) &#123; builder.bulidA(); builder.bulidB(); builder.bulidC(); builder.bulidD(); return builder.getProduct(); &#125;&#125; 1234567891011/** * Test.java * 测试类 */public class Test &#123; public static void main(String[] args) &#123; Director director = new Director(); Product create = director.create(new ConcreteBuilder()); System.out.println(create.toString()); &#125;&#125; 总结 Builder 抽象类定义构建的方法 具体实现类实现Builder相关的方法-叫具体建造者 指挥者操作操作具体建造者按照顺序创建对象 产品类有大量属性 优点 按照顺序创建对象 创建代码可读性好 隐藏对象大量属性,可以设置一些属性的默认值 缺点 代码冗余 具体建造者内部代码复杂,代码可读性差 具体实现 protobuf生成的实体类 1234SimpleRequest.Builder builder = SimpleRequest.newBuilder();builder.setId(12341);builder.setName(&quot;你好&quot;);SimpleRequest request = builder.build();
